<?php
require 'config.php'; require_role('driver');
$driverPk=(int)$_SESSION['driver_pk'];
$r1=['Centro Lumbia','Palalan Road','Masterson Ave.','Kagay-an Bridge','Rodelsa Circle','Tomas Saco St.','Fernandez St.','Corrales Ave.','Hayes St.','Cogon Public Market'];
$r2=['Centro Lumbia','F. Delima St.','Masterson Ave.','Macapagal Drive','SM Bypass Road','C. Diel St.','Villarin St.','Max Suniel St.','V. Neri St.','Carmen Public Market'];
$froms=['Lumbia','Carmen','Cogon'];$tos=['Carmen','Cogon','Lumbia'];
function route_code($from,$to){return ($from==='Lumbia'&&$to==='Cogon')?'R1':(($from==='Lumbia'&&$to==='Carmen')?'R2':null);}
try{
 $action=$_POST['action']??'';
 $st=$pdo->prepare('SELECT * FROM drivers WHERE id=? AND is_archived=0');$st->execute([$driverPk]);$driver=$st->fetch();if(!$driver)throw new Exception('Driver account is unavailable.');
 if($action==='set_departure'){
  $from=$_POST['from'];$to=$_POST['to'];$hour=(int)$_POST['hour'];$period=$_POST['period'];$route=route_code($from,$to);if(!$route)throw new Exception('For TranSeat, use Lumbia-Cogon (R1) or Lumbia-Carmen (R2).');
  $st=$pdo->prepare('SELECT * FROM departures WHERE driver_pk=?');$st->execute([$driverPk]);$existing=$st->fetch();
  if($existing){$q=$pdo->prepare('UPDATE departures SET route_code=?,from_location=?,to_location=?,departure_hour=?,departure_period=? WHERE driver_pk=?');$q->execute([$route,$from,$to,$hour,$period,$driverPk]);}
  else{$q=$pdo->prepare('INSERT INTO departures(driver_pk,route_code,from_location,to_location,departure_hour,departure_period,current_stop,is_active,round_trips) VALUES(?,?,?,?,?,?,?,0,0)');$q->execute([$driverPk,$route,$from,$to,$hour,$period,$route==='R1'?$r1[0]:$r2[0]]);}
  go('driver.php','Departure Set saved for '.$route.'.');
 }
 if($action==='toggle_departure'){
  $on=(int)$_POST['on'];$st=$pdo->prepare('SELECT * FROM departures WHERE driver_pk=?');$st->execute([$driverPk]);$d=$st->fetch();if(!$d)throw new Exception('Set your departure route and time first.');
  if($on){$newRound=(int)$d['round_trips']+($d['is_active']?0:1);$pdo->prepare('UPDATE departures SET is_active=1,round_trips=?,departed_at=NOW() WHERE driver_pk=?')->execute([$newRound,$driverPk]);go('driver.php','Departure is now ON. Passengers can see you as available.');}
  else{$pdo->prepare('UPDATE departures SET is_active=0 WHERE driver_pk=?')->execute([$driverPk]);go('driver.php','Departure is now OFF.');}
 }
 if($action==='set_stop'){
  $route=$_POST['route'];$stop=trim($_POST['stop']);$valid=$route==='R1'?$r1:$r2;if(!in_array($stop,$valid,true))throw new Exception('Invalid route stop.');
  $pdo->prepare('UPDATE departures SET route_code=?,current_stop=? WHERE driver_pk=?')->execute([$route,$stop,$driverPk]);go('driver.php','Current stop updated.');
 }
}catch(Throwable $e){go('driver.php',$e->getMessage(),'error');}
$st=$pdo->prepare('SELECT * FROM departures WHERE driver_pk=?');$st->execute([$driverPk]);$d=$st->fetch();$f=flash();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TranSeat - Driver</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><div class="brand"><img src="assets/logo.jpg">Driver Dashboard</div><nav class="nav"><span><?=e($driver['driver_name'])?> (<?=e($driver['driver_id'])?>)</span><a href="logout.php">Log Out</a></nav></header><main class="container"><?php if($f):?><div class="message <?=$f['type']?>"><?=e($f['message'])?></div><?php endif;?><section class="card"><h2>Departure Setter</h2><p class="small">Set your route and departure time before turning the departure toggle ON.</p><form method="post"><input type="hidden" name="action" value="set_departure"><div class="form-grid"><div class="field"><label>From</label><select name="from" id="itmFrom"><?php foreach($froms as $v):?><option <?=($d&&$d['from_location']===$v?'selected':'')?> ><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label>To</label><select name="to" id="itmTo"><?php foreach($tos as $v):?><option <?=($d&&$d['to_location']===$v?'selected':'')?> ><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label>Departure Time</label><div style="display:flex;gap:6px"><select name="hour" id="itmDeparture"><?php for($i=1;$i<=12;$i++):?><option <?=($d&&(int)$d['departure_hour']===$i?'selected':'')?> ><?=$i?></option><?php endfor;?></select><select name="period" id="itmTime"><option <?=($d&&$d['departure_period']==='AM'?'selected':'')?>>AM</option><option <?=($d&&$d['departure_period']==='PM'?'selected':'')?>>PM</option></select></div></div></div><div class="actions"><button class="btn" name="save" id="btnSet">Set</button></div></form><form method="post" class="actions"><input type="hidden" name="action" value="toggle_departure"><input type="hidden" name="on" value="<?=($d&&$d['is_active'])?'0':'1'?>"><button class="btn toggle <?=($d&&$d['is_active'])?'on':'off'?>" id="toggleDeparture"><?=($d&&$d['is_active'])?'Departure ON':'Departure OFF'?></button></form></section>
<section class="card"><h2>Route R1 (Lumbia-Cogon)</h2><div class="route-panel"><form method="post"><input type="hidden" name="action" value="set_stop"><input type="hidden" name="route" value="R1"><div class="field"><label>Current Stop</label><select name="stop" id="itmR1"><?php foreach($r1 as $v):?><option <?=($d&&$d['current_stop']===$v&&$d['route_code']==='R1'?'selected':'')?>><?=e($v)?></option><?php endforeach;?></select></div><div class="actions"><button class="btn <?=($d&&$d['route_code']==='R1'&&$d['is_active']?'success':'secondary')?>" id="toggleSetR1">Set R1 Stop</button></div></form></div></section>
<section class="card"><h2>Route R2 (Lumbia-Carmen)</h2><div class="route-panel"><form method="post"><input type="hidden" name="action" value="set_stop"><input type="hidden" name="route" value="R2"><div class="field"><label>Current Stop</label><select name="stop" id="itmR2"><?php foreach($r2 as $v):?><option <?=($d&&$d['current_stop']===$v&&$d['route_code']==='R2'?'selected':'')?>><?=e($v)?></option><?php endforeach;?></select></div><div class="actions"><button class="btn <?=($d&&$d['route_code']==='R2'&&$d['is_active']?'success':'secondary')?>" id="toggleSetR2">Set R2 Stop</button></div></form></div></section>
<section class="card"><h2>Current Departure</h2><?php if($d):?><p><b>Route:</b> <?=e($d['route_code'])?> &nbsp; <b>From:</b> <?=e($d['from_location'])?> &nbsp; <b>To:</b> <?=e($d['to_location'])?></p><p><b>Departure:</b> <?=e($d['departure_hour'])?> <?=e($d['departure_period'])?> &nbsp; <b>Current Stop:</b> <?=e($d['current_stop'])?> &nbsp; <b>Round Trips:</b> <?=e($d['round_trips'])?></p><p><span class="badge <?=($d['is_active']?'available':'unavailable')?>"><?=($d['is_active']?'Available to passengers':'Not Available')?></span></p><?php else:?><p>No departure has been set yet.</p><?php endif;?></section></main></body></html>